export class ExecutionReportValidationError extends Error {}

/** Decode the report while retaining evidence labels as unverified model data.
 * Retained v1 reports may carry completedSteps. New tool output omits that
 * duplicate account; the separate recap supplies chronological observations. */
export function validateExecutionReport(value) {
  if (
    !object(value, ["status"]) ||
    !["needs_input", "stuck", "blocked", "complete"].includes(value.status)
  )
    throw new ExecutionReportValidationError(
      "Malformed execution_status report; execution incomplete",
    );
  return structuredClone(value);
}
// Legacy presentation hints are decorative. Keep malformed originals in the
// saved model report, but do not send an unusable hint through typed transports
// or turn it into an asserted source quotation.
const questionView = (value) => {
  const { id, question, kind, presentation } = structuredClone(value);
  // The category only labels a question; answers bind by its unchanged ID.
  // Keep unusable labels in the original report, not the known question view.
  const fields = { id, question, kind: text(kind) ? kind : "task-scope" };
  if (presentation === undefined) return fields;
  try {
    return {
      ...fields,
      presentation: validateClarificationPresentation(presentation),
    };
  } catch {
    return fields;
  }
};
// Keep each usable original question, including repeated original IDs. Answer
// objects remain keyed by those IDs; never invent IDs, merge wording or split a
// caller's value. Unusable entries remain in the private authored report.
const questionViews = (value) =>
  (Array.isArray(value) ? value : [])
    .filter(
      (q) =>
        object(q, ["id", "question"]) &&
        typeof q.id === "string" &&
        text(q.question),
    )
    .map(questionView);
export const clarificationId = (responseId, callId) =>
  createHash("sha256")
    .update(responseId + "\0" + callId)
    .digest("hex");

export function createExecutionStatus({
  initialEffort = "low",
  effortRecovery = true,
  saved,
  save,
  check,
  signal,
  deadline,
  executionDeadlineSignal,
  requestClarification,
  retainEvidence,
  registerSensitiveAnswers,
}) {
  if (
    !["none", "low", "medium", "high", "xhigh", "max"].includes(initialEffort)
  )
    throw Error("Invalid initial Runner reasoning");
  let pendingClarification,
    resumeEpoch = 0;
  let recoveryUsed = false,
    latestReport = null;
  const reports = [],
    recoveryHistory = [],
    effortAccounting = {
      low: 0,
      medium: 0,
      ...(!["low", "medium"].includes(initialEffort)
        ? { [initialEffort]: 0 }
        : {}),
    };
  const snapshot = () => ({
    executionReport: latestReport
      ? {
          schema: Object.hasOwn(latestReport.report, "completedSteps")
            ? "loki.runner.execution-report/1"
            : "loki.runner.execution-report/2",
          status: latestReport.report.status,
          ...reportDetails(latestReport.report),
          questions: questionViews(latestReport.report.questions),
          ...(["known", "uncertain"].includes(latestReport.report.effects)
            ? { effects: latestReport.report.effects }
            : {}),
          basis: "model-authored-unverified",
          responseId: latestReport.providerResponseId,
          callId: latestReport.callId,
        }
      : null,
    recovery: {
      ...(!effortRecovery ? { enabled: false } : {}),
      used: recoveryUsed,
      initialEffort,
      currentEffort: recoveryUsed ? "medium" : initialEffort,
      transitions: recoveryHistory,
    },
    effortAccounting,
  });
  const persist = () =>
    save("execution-status.json", {
      schema: "loki.runner.execution-status/1",
      ...snapshot(),
      reports,
    });
  async function retainReport(item, responseId, providerCall) {
    if (!text(responseId) || !text(item.call_id))
      throw Error("Missing execution report correlation");
    let value, report;
    try {
      value = JSON.parse(item.arguments);
      report = validateExecutionReport(value);
    } catch (error) {
      if (!(
        error instanceof SyntaxError ||
        error instanceof ExecutionReportValidationError
      ))
        throw error;
      const invalid = new ExecutionReportValidationError(error.message);
      invalid.effectsUncertain = value?.effects === "uncertain";
      throw invalid;
    }
    // Model labels do not authorize a file read. Only actual records from this
    // Run's host ledger can be retained as evidence; keep every original label
    // in the unverified report even when it has no corresponding saved record.
    const details = reportDetails(report);
    const knownEvidence = details.evidence.filter((name) => saved.has(name));
    const record = {
      report,
      providerResponseId: responseId,
      callId: item.call_id,
      providerCall,
      responseReference: saved.get(`response-${providerCall}.json`) ?? null,
      evidenceReferences: retainEvidence
        ? await retainEvidence(knownEvidence, providerCall)
        : knownEvidence.map((name) => saved.get(name)),
      provenance: "model-authored-unverified",
    };
    latestReport = record;
    reports.push(record);
    await persist();
    return { report, details };
  }
  async function call(
    item,
    responseId,
    providerCall,
    admittedEpoch = resumeEpoch,
    testQueueClosed = false,
  ) {
    check();
    const { report, details } = await retainReport(
      item,
      responseId,
      providerCall,
    );
    check();
    const output = (value) => ({
      type: "function_call_output",
      call_id: item.call_id,
      output: JSON.stringify(value),
    });
    // Keep prompts general. Only give interaction advice that applies across common tasks; keep case-specific steps in tests.
    const superseded = () => ({
      output: output({
        error: {
          code: "clarification_superseded",
          message:
            "Browser control returned. The original question remains unanswered; continue from the current browser observation.",
        },
      }),
    });
    if (report.status === "needs_input" && admittedEpoch !== resumeEpoch) {
      latestReport = null;
      await persist();
      return superseded();
    }
    // With no remaining browser tests, a retained assessment ends the Run
    // even when it honestly reports unfinished work.
    if (testQueueClosed || report.status === "complete")
      return { complete: true, terminalReason: details.reason };
    if (report.status === "stuck" || report.status === "blocked") {
      if (
        report.status === "stuck" &&
        effortRecovery &&
        !recoveryUsed &&
        initialEffort === "low"
      ) {
        recoveryUsed = true;
        recoveryHistory.push({
          responseId,
          callId: item.call_id,
          from: "low",
          to: "medium",
          reason: details.reason,
        });
        await persist();
        check();
      }
      return {
        output: output({
          recorded: true,
        }),
      };
    }
    const questions = questionViews(report.questions);
    if (!questions.length || typeof requestClarification !== "function")
      return {
        output: output({
          error: {
            code: "clarification_unavailable",
            message: questions.length
              ? "Caller clarification callback unavailable"
              : "No usable original question is available; the report is retained.",
          },
        }),
      };
    const request = {
      schema: "loki.runner.clarification/1",
      clarificationId: clarificationId(responseId, item.call_id),
      providerResponseId: responseId,
      callId: item.call_id,
      reason: details.reason,
      completedSteps: details.completedSteps ?? [],
      remainingSteps: details.remainingSteps,
      evidence: details.evidence,
      questions,
      provenance: "model-authored-unverified",
    };
    const row = {
      request: { ...request, questions: structuredClone(report.questions) },
      answer: null,
      status: "waiting",
    };
    await save(`clarification-${request.clarificationId}.json`, row);
    const remaining =
      (typeof deadline === "function" ? deadline() : deadline) - Date.now();
    if (remaining <= 0) throw Error("Time limit");
    const deadlineSignal =
      executionDeadlineSignal ??
      (Number.isFinite(remaining) ? AbortSignal.timeout(remaining) : undefined);
    const lifecycleSignal = AbortSignal.any([
      ...(signal ? [signal] : []),
      // A viewer-enabled Run already owns a pausable active-budget signal.
      // A second fixed wall timer would expire a pending question during takeover.
      ...(deadlineSignal ? [deadlineSignal] : []),
    ]);
    const controller = new AbortController();
    const waitSignal = AbortSignal.any([lifecycleSignal, controller.signal]);
    let settle;
    const pending = {
      controller,
      settled: new Promise((resolve) => {
        settle = resolve;
      }),
      failure: undefined,
    };
    pendingClarification = pending;
    let abort;
    const interrupted = new Promise((_, reject) => {
      abort = () =>
        reject(
          Error(
            "Clarification interrupted by Stop or original deadline; do not replay",
          ),
        );
      lifecycleSignal.addEventListener("abort", abort, { once: true });
      if (lifecycleSignal.aborted) abort();
    });
    void interrupted.catch(() => {});
    const finish = async () => {
      try {
        if (row.status === "waiting") row.status = "interrupted";
        await save(`clarification-${request.clarificationId}.json`, row);
        if (row.status === "answered" || controller.signal.aborted) {
          // This report predates the answer or browser handoff. Keep its original
          // record in reports, but do not present it as current progress if the
          // continuation ends before the model submits another status report.
          latestReport = null;
          await persist();
        }
      } catch (error) {
        pending.failure = { error };
        throw error;
      } finally {
        if (pendingClarification === pending) pendingClarification = undefined;
        settle();
      }
    };
    let callbackAnswer;
    try {
      check();
      if (admittedEpoch !== resumeEpoch) {
        controller.abort(
          Object.assign(Error("Browser control already returned"), {
            code: "loki.runner.browser-control/1",
          }),
        );
        return superseded();
      }
      const answer = await Promise.race([
        requestClarification(structuredClone(request), waitSignal),
        interrupted,
      ]);
      callbackAnswer = answer;
      registerSensitiveAnswers?.(clarificationAnswerSecrets(answer));
      row.answer = structuredClone(answer);
      check();
      if (lifecycleSignal.aborted)
        throw Error("Clarification deadline exceeded");
      row.status = "answered";
      return { output: output(answer ?? null) };
    } catch (error) {
      check();
      if (lifecycleSignal.aborted) throw error;
      if (controller.signal.aborted) {
        const cancelled =
          error === controller.signal.reason ||
          (error instanceof Error &&
            "code" in error &&
            error.code === "loki.runner.clarification-interrupted/1");
        if (!cancelled) {
          pending.failure = { error };
          throw error;
        }
        return superseded();
      }
      await save(`clarification-error-${request.clarificationId}.json`, {
        clarificationId: request.clarificationId,
        providerResponseId: responseId,
        callId: item.call_id,
        error: String(error),
        ...(callbackAnswer !== undefined ? { answer: callbackAnswer } : {}),
      });
      return {
        output: output({
          error: {
            code: "clarification_failed",
            message:
              "Caller input was not delivered. The original question remains unanswered.",
          },
        }),
      };
    } finally {
      lifecycleSignal.removeEventListener("abort", abort);
      await finish();
    }
  }
  return {
    clarificationEpoch: () => resumeEpoch,
    async interruptClarificationForBrowserControl() {
      resumeEpoch++;
      const pending = pendingClarification;
      if (!pending) return;
      pending.controller.abort(
        Object.assign(Error("Browser control returned; question superseded"), {
          code: "loki.runner.browser-control/1",
        }),
      );
      await pending.settled;
      if (pending.failure) throw pending.failure.error;
    },
    call: (item, responseId, providerCall) =>
      call(item, responseId, providerCall),
    retainReport,
    callAdmitted: (epoch, item, responseId, providerCall, testQueueClosed) =>
      call(item, responseId, providerCall, epoch, testQueueClosed),
    snapshot,
    provenance: () =>
      latestReport
        ? {
            responseReference: latestReport.responseReference,
            evidenceReferences: latestReport.evidenceReferences,
            providerCall: latestReport.providerCall,
          }
        : null,
    effort: () => (recoveryUsed ? "medium" : initialEffort),
    account: (effort) => effortAccounting[effort]++,
  };
}
